-- V5：定时扫描的调度项（P4，设计见 docs/sensitive-data-design.md §4.6 / §5.6.3）
--
-- 与 MySQL 侧同一张表、同一份实体派生，只是方言不同：自增列是
-- generated by default as identity、注释是独立的 comment on ... is '...'。
-- 内容与 sql/schema-postgres.sql 里那份全量快照逐字一致，改结构仍然只改实体，
-- 再依次跑 ./scripts/gen-postgres-ddl.sh 与 scripts/gen-flyway-baseline.py。
--
-- 为什么需要这张表、为什么 next_run_at 与 entity_version 要分开、为什么存 cron 而不是
-- 间隔秒数，见 MySQL 那份开头的说明（两份共用一份理由，不各写一遍——两个版本对同一件事
-- 的措辞漂移，比没有注释更坏）。

create table lakehouse_sensitivity_schedule (
        enabled_flag boolean not null,
        entity_version integer not null,
        sample_size integer not null,
        created_at bigint,
        id bigint generated by default as identity,
        last_run_at bigint,
        next_run_at bigint,
        updated_at bigint,
        execution varchar(16) not null,
        mode varchar(16) not null,
        catalog_name varchar(64) not null,
        cron varchar(64) not null,
        name varchar(128) not null,
        table_name varchar(512),
        created_by varchar(255),
        database_name varchar(255),
        owner varchar(255),
        updated_by varchar(255),
        primary key (id),
        constraint uk_sensitivity_schedule unique (name)
    );

comment on table lakehouse_sensitivity_schedule is
    '定时扫描的调度项（自建调度：cron + next_run_at 抢占令牌）';

comment on column lakehouse_sensitivity_schedule.enabled_flag is
    '是否启用；停用后不再触发，历史扫描仍按 schedule_name 可查';

comment on column lakehouse_sensitivity_schedule.entity_version is
    '乐观并发版本号（人工编辑用），与 next_run_at 的抢占语义分开';

comment on column lakehouse_sensitivity_schedule.sample_size is
    '采样行上限（默认 2000）';

comment on column lakehouse_sensitivity_schedule.created_at is
    '创建时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_schedule.id is
    '自增主键';

comment on column lakehouse_sensitivity_schedule.last_run_at is
    '上次触发的时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_schedule.next_run_at is
    '下次触发时刻（epoch 毫秒）；调度器抢占的 CAS 条件';

comment on column lakehouse_sensitivity_schedule.updated_at is
    '最后更新时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_schedule.execution is
    '执行位置：IN_PROCESS / SPARK（未填时取三层覆盖的生效值）';

comment on column lakehouse_sensitivity_schedule.mode is
    '扫描模式：METADATA_ONLY / SAMPLED';

comment on column lakehouse_sensitivity_schedule.catalog_name is
    'catalog 名';

comment on column lakehouse_sensitivity_schedule.cron is
    'cron 表达式（5 段或 6 段，秒级可选）';

comment on column lakehouse_sensitivity_schedule.name is
    '调度项名（唯一；扫描表按它回查历史，因此不可改名）';

comment on column lakehouse_sensitivity_schedule.table_name is
    '表名；catalog / 库级调度为空';

comment on column lakehouse_sensitivity_schedule.created_by is
    '创建者主体名（写入前已按列宽归一化）';

comment on column lakehouse_sensitivity_schedule.database_name is
    '库名；catalog 级调度为空';

comment on column lakehouse_sensitivity_schedule.owner is
    '记录归属主体（展示与过滤用，不参与授权判定）';

comment on column lakehouse_sensitivity_schedule.updated_by is
    '最后更新者主体名（写入前已按列宽归一化）';

create index ix_sensitivity_schedule_catalog
       on lakehouse_sensitivity_schedule (catalog_name);
